function balanceLabel(lever){const words={'role:tank:health':'Tank health','role:healer:healing':'Healer healing','role:controller:control':'Controller control','role:damage:damage':'Damage dealer damage','weapon:melee:damage':'Melee weapon damage','weapon:ranged:damage':'Ranged weapon damage','weapon:arcane:damage':'Arcane weapon damage','kit:healing:output':'Healing kits','kit:control:output':'Control kits','ability:healing:output':'Healing abilities','ability:control:output':'Control abilities','target:fortified':'Fortified protection','target:healing':'Healing output','target:control':'Control duration','target:dive':'Dive damage'};const parts=lever.split(':');if(parts[0]==='role'&&parts[2]==='stat')return (parts[1][0].toUpperCase()+parts[1].slice(1))+' '+parts[3]+' effective stat';if(parts[0]==='role'&&parts[2]==='ability')return (parts[1][0].toUpperCase()+parts[1].slice(1))+' '+balanceLabel(parts.slice(2).join(':'));if(parts[0]==='stat')return parts[1]+' effective stat';if(parts[0]==='ability'&&['cooldown','potency','healing','duration'].includes(parts[2]))return (Object.values(globalThis.CURRENT_CLASS_ABILITIES.abilities).find(p=>p.id===parts[1])?.name??parts[1])+' '+({potency:'cast power',healing:'healing',duration:'effect duration',cooldown:'cooldown'}[parts[2]]);return words[lever]??lever;}
const percent=n=>`${n>0?'+':''}${Math.round(n*1000)/10}%`;
function proposeBalance(balance,{season,phase}){
 const rates=balanceRates(balance.samples),candidates={};for(const r of rates){const [lo,hi]=balanceEvidence(r);if(r.games<BALANCE_LIMITS.minimumGames||r.rate>=.45&&r.rate<=.55||lo<=.5&&hi>=.5)continue;const lever=balanceLever(r.key),confidence=Math.abs(r.rate-.5)*Math.sqrt(r.games);if(!candidates[lever]||confidence>candidates[lever].confidence)candidates[lever]={...r,confidence};}
 const multipliers={...balance.profile.multipliers},changes=[];const limit=phase==='halfway'?.015:.03;
 for(const [lever,r]of Object.entries(candidates).sort(([a],[b])=>a.localeCompare(b))){const before=multipliers[lever]??1,step=-Math.sign(r.rate-.5)*Math.min(limit,Math.abs(r.rate-.5)*.1),bounded=Math.max(.85,Math.min(1.15,before+step*Math.min(before,1))),after=(step<0?Math.ceil((bounded-1e-9)*10000):Math.floor((bounded+1e-9)*10000))/10000;if(after===before)continue;multipliers[lever]=after;changes.push({lever,from:before,to:after,games:r.games,winRate:Math.round(r.rate*1000)/10,note:`${balanceLabel(lever)} ${percent(after/before-1)} (${Math.round(r.rate*100)}% wins in ${r.games} comparable games)`});}
 if(!changes.length)return null;return {id:`${season}.${phase==='halfway'?'mid':'end'}.${balance.history.length+1}`,season,phase,changes,profile:{id:`${season}.${phase==='halfway'?'mid':'end'}.${balance.history.length+1}`,multipliers}};
}
function applyBalanceCheckpoint(balance,context){if(!balance.enabled)return null;const patch=proposeBalance(balance,context);if(patch){balance.profile=structuredClone(patch.profile);balance.history.push(patch);}balance.samples=[];return patch;}
function patchFactor(profile,key){return profile?.multipliers?.[key]??1;}
function validateBalanceProfile(profile){if(!profile||typeof profile.id!=='string'||!profile.multipliers||Array.isArray(profile.multipliers))throw new Error('Invalid saved balance patch.');const ids=new Set(Object.values(globalThis.CURRENT_CLASS_ABILITIES.abilities).map(p=>p.id));for(const [key,n]of Object.entries(profile.multipliers)){const raw=key.split(':'),p=raw[0]==='role'&&['stat','ability'].includes(raw[2])&&['tank','healer','controller','damage'].includes(raw[1])?raw.slice(2):raw,specific=p[0]==='stat'&&p.length===2&&['STR','SPD','DUR','IQ','MAG'].includes(p[1])||p[0]==='ability'&&p.length===3&&['cooldown','potency','healing','duration'].includes(p[2])&&ids.has(p[1]);if(!specific&&!/^(role:(tank:health|healer:healing|controller:control|damage:damage)|weapon:(melee|ranged|arcane):damage|(kit|ability):(healing|control):output|target:(fortified|healing|control|dive))$/.test(key)||!Number.isFinite(n)||n<.7||n>1.3)throw new Error('Invalid saved balance multiplier.');}return structuredClone(profile);}

// The team cast: ten classes, each with subclasses that set the role, the weapon family
// and the two abilities. 2v2, 3v3 and 5v5 fighters come from this cast instead of the duel wheel: races keep their stat
// modifiers, and nobody has a weakness. Every class is equally likely, then every subclass of that class.
// Roles: the cast's roles (shown in the game) and the engine role each one plays (support → controller, bruiser →
// melee damage).
const CAST_ROLES=Object.freeze({tank:'tank',healer:'healer',controller:'controller',damage:'damage',support:'controller',bruiser:'damage'});
const CAST_ROLE_LABELS=Object.freeze({tank:'Tank',healer:'Healer',controller:'Controller',damage:'Damage',support:'Support',bruiser:'Bruiser'});
